WITH eligible AS (SELECT s.* FROM suppliers s WHERE NOT EXISTS (SELECT 1 FROM products c WHERE c.supplier_id = s.id AND c.launch_date BETWEEN '2023-12-01' AND '2024-08-15')), kept AS (SELECT s.* FROM eligible s WHERE EXISTS (SELECT 1 FROM products x WHERE x.supplier_id = s.id AND x.brand = 'Acme')), enriched AS (SELECT id, supplier_name, country, city, MIN(rating) OVER w_hist AS running_min_rating, SUM(rating) OVER w_hist AS running_sum_rating, MAX(rating) OVER w_hist AS running_max_rating, AVG(rating) OVER w_grp AS rating_avg_6 FROM kept WINDOW w_hist AS (PARTITION BY country, city ORDER BY rating, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW), w_grp AS (PARTITION BY country ORDER BY rating, id ROWS BETWEEN 6 PRECEDING AND CURRENT ROW)), filtered AS (SELECT id, city, running_min_rating, running_sum_rating, running_max_rating, INITCAP(TRIM(city)) AS city_title, running_sum_rating - rating_avg_6 AS running_sum_rating_minus_rating_avg_6 FROM enriched WHERE city IS NOT NULL), latest_match AS (SELECT s.id, s.running_sum_rating, s.running_sum_rating_minus_rating_avg_6, latest.product_cost, latest.price FROM filtered s LEFT JOIN LATERAL (SELECT c.cost AS product_cost, c.price FROM products c WHERE c.supplier_id = s.id ORDER BY c.stock_qty DESC, c.id DESC LIMIT 1) latest ON TRUE), not_flagged AS (SELECT s.* FROM latest_match s WHERE NOT EXISTS (SELECT 1 FROM products ch WHERE ch.supplier_id = s.id AND ch.category NOT IN ('Fashion', 'Electronics'))), enriched_suppliers AS (SELECT *, SUM(product_cost) OVER (ORDER BY product_cost, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_product_cost, SUM(running_sum_rating) OVER w_grp AS cumulative_running_sum_rating, ROW_NUMBER() OVER (ORDER BY product_cost DESC, id) AS event_seq, AVG(running_sum_rating) OVER (ORDER BY running_sum_rating, id ROWS BETWEEN 3 PRECEDING AND CURRENT ROW) AS running_sum_rating_avg_3 FROM not_flagged WINDOW w_grp AS (ORDER BY price, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)) SELECT CASE WHEN product_cost >= 720 THEN 'HIGH' ELSE 'LOW' END AS product_cost_tier, COUNT(DISTINCT id) AS distinct_ids, COUNT(*) AS num_rows, APPROX_PERCENTILE(cumulative_product_cost, 0.5) AS cumulative_product_cost_p50, ROUND(AVG(cumulative_running_sum_rating), 2) AS avg_cumulative_running_sum_rating, ROUND(AVG(price), 2) AS avg_price FROM enriched_suppliers GROUP BY CASE WHEN product_cost >= 720 THEN 'HIGH' ELSE 'LOW' END ORDER BY cumulative_product_cost_p50;
